import{readFileSync,writeFileSync}from'node:fs';import{gunzipSync}from'node:zlib';import{createHash}from'node:crypto';import{createPressQuarterV272}from'__REPO__/src/app/src/PressQuarterV272';import source from'__REPO__/src/app/src/data/pressQuarterV272.json';
const R='__REPO__',E='__OUTPUT__',evidenceBytes=readFileSync(R+'/geo_data/regierungsviertel/press-quarter-v272-source.json.gz'),evidence=JSON.parse(gunzipSync(evidenceBytes).toString()),prisms=JSON.parse(readFileSync(R+'/src/app/public/mesh/regierungsviertel/lod2-prisms.json','utf8')).buildings,owner=prisms.find((p:any)=>p.id==='32698095'),sha=(b:any)=>createHash('sha256').update(b).digest('hex'),raw=(a:any)=>Buffer.from(a.buffer,a.byteOffset,a.byteLength).toString('base64');
const records:any[]=[];for(const native of[false,true]){const rows=native?[...evidence.nativeBlocks,...evidence.nativeDetails]:evidence.facadeBoxes,encoded=Buffer.from(native?source.nativeBoxes:source.facadeBoxes,'base64'),observed=new Float32Array(encoded.buffer,encoded.byteOffset,encoded.byteLength/4),expected=new Float32Array(rows.flatMap((r:any)=>r.slice(0,8)));if(raw(observed)!==raw(expected))throw Error('Fulloriginalowner-sourcewordidentityfailed');
 const root=createPressQuarterV272(native),mesh=root.children.find((o:any)=>o.isInstancedMesh)as any,indices=rows.flatMap((r:any,i:number)=>r[9]==='32698095'?[i]:[]);if(indices.length!==(native?1936:616))throw Error('Exact616/1936sourceownerrequired');const m=mesh.instanceMatrix.array,c=mesh.instanceColor.array,matrices=new Float32Array(indices.length*16),colors=new Float32Array(indices.length*3);for(let i=0;i<indices.length;i++){matrices.set(m.subarray(indices[i]*16,indices[i]*16+16),i*16);colors.set(c.subarray(indices[i]*3,indices[i]*3+3),i*3);}
 const component={name:mesh.name,kind:'instances',retire:true,attributes:Object.fromEntries(Object.entries(mesh.geometry.attributes).map(([k,a]:any)=>[k,{type:a.array.constructor.name,itemSize:a.itemSize,normalized:a.normalized,bytes:raw(a.array)}])),index:mesh.geometry.index?{type:mesh.geometry.index.array.constructor.name,bytes:raw(mesh.geometry.index.array)}:null,instances:{count:indices.length,matrix:raw(matrices),color:raw(colors)}};
 records.push({native,groupName:root.name,actualHostCount:mesh.count,sourceOwner:'32698095',sourcePrism:owner,selectedGlobalRows:indices,fullOriginalPackedBoxRowsSha256:sha(encoded),fullMatrixSha256:sha(Buffer.from(m.buffer,m.byteOffset,m.byteLength)),fullColorSha256:sha(Buffer.from(c.buffer,c.byteOffset,c.byteLength)),component,otherGroupChildren:root.children.filter(o=>o!==mesh).map((o:any)=>({name:o.name,attributes:Object.fromEntries(Object.entries(o.geometry.attributes).map(([k,a]:any)=>[k,sha(Buffer.from(a.array.buffer,a.array.byteOffset,a.array.byteLength))]))}))});
 const resources=new Set<any>();root.traverse((o:any)=>{if(o.geometry)resources.add(o.geometry);if(o.isInstancedMesh)resources.add(o);for(const q of[o.material,o.userData.dayMaterial,o.userData.nightMaterial].flat())if(q?.dispose)resources.add(q);});for(const q of resources)q.dispose();root.clear();}
writeFileSync(E+'/'+(process.argv[2]??'unknown')+'.json',JSON.stringify({schemaVersion:1,engine:process.versions,sourceEvidenceSha256:sha(evidenceBytes),sourceRuntimeSha256:sha(readFileSync(R+'/src/app/src/data/pressQuarterV272.json')),records}));console.log('captured2families',records.map(r=>[r.native,r.component.instances.count,r.actualHostCount]));
